mapper.select:
( SELECT pr.id AS moduleId, 'Bill' AS type, pr.id AS id, COALESCE(pr.order_date, '') AS `date`, COALESCE((SELECT pr_code FROM purchase_requests WHERE id = pr.purchase_request_id), '') AS prCode, pr.po_code AS pvCode, CASE WHEN (pr.pv_request_id IS NOT NULL) THEN COALESCE((SELECT code FROM pv_requests WHERE id = pr.pv_request_id LIMIT 1), '') ELSE COALESCE((SELECT code FROM pv_requests WHERE id IN (SELECT pv_request_id FROM pv_request_orders WHERE order_id = pr.id AND status = 3) LIMIT 1), '') END AS erNumber, CASE WHEN (pr.pv_request_id IS NULL AND (SELECT total_amount_approved FROM pv_requests WHERE id IN (SELECT pv_request_id FROM pv_request_orders WHERE order_id = 1 AND status = 3)) IS NOT NULL) THEN (SELECT total_amount_approved FROM pv_requests WHERE id IN (SELECT pv_request_id FROM pv_request_orders WHERE order_id = pr.id AND status = 3)) WHEN (pr.pv_request_id IS NOT NULL) THEN (SELECT total_amount_approved FROM pv_requests WHERE id = pr.pv_request_id) WHEN (pr.pv_request_id IS NULL) THEN (SELECT SUM(deposit_amount) FROM pv_request_apply_deposits WHERE pv_request_id = pr.pv_request_id AND is_approved = 1 AND pay_bill_apply = 0) ELSE (SELECT SUM(deposit_amount) FROM pv_request_apply_deposits WHERE is_approved = 1 AND pay_bill_apply = 0 AND pv_request_id IN (SELECT pv_request_id FROM pv_request_orders WHERE order_id = pr.id AND status = 3)) END AS erAmount, pr.po_code AS reference, pr.branch_id AS branchId, (SELECT name FROM branches WHERE id = pr.branch_id) AS branchName, loc.id AS locationId, COALESCE(loc.name, '') AS locationName, v.name AS vendorName, v.id AS vendorId, '' AS chartAccountId, pr.total_amount AS totalAmount, pr. balance AS amountDue, pr.balance AS balance, COALESCE(pr.due_date, '') AS aging, pr.pv_request_id AS pvId, '' AS pvAppAmt, '' AS pvAmt, '' AS pvRequestId, '' AS landedCostId, COALESCE(pr.note, '') AS memo FROM purchase_orders pr INNER JOIN locations loc ON pr.location_id = loc.id INNER JOIN vendors v ON pr.vendor_id = v.id WHERE pr.status > 0 AND pr.balance > 0
AND pr.company_id = #{filter.companyId}
AND pr.vendor_id = #{filter.vendorId}
AND pr.location_id = #{filter.locationId}
) UNION ALL ( SELECT gl.id AS moduleId, 'Journal' AS type, gld.id AS id, COALESCE(gl.date, '') AS `date`, (SELECT pr_code FROM purchase_requests WHERE id IN (SELECT purchase_request_id FROM purchase_orders WHERE id = gl.purchase_order_id) LIMIT 1) AS prCode, COALESCE((SELECT po_code FROM purchase_orders WHERE id = gl.purchase_order_id), '') AS pvCode, COALESCE((SELECT code FROM pv_requests WHERE id = gl.pv_id), '') AS erNumber, null AS erAmount, gl.reference AS reference, (SELECT branch_id FROM general_ledger_details WHERE general_ledger_id = gl.id LIMIT 1) AS branchId, (SELECT name FROM branches WHERE id = (SELECT branch_id FROM general_ledger_details WHERE general_ledger_id = gl.id LIMIT 1)) AS branchName, COALESCE(gld.location_id, '') AS locationId, '' AS locationName, v.name AS vendorName, gld.vendor_id AS vendorId, gld.chart_account_id AS chartAccountId, IFNULL(gld.credit, 0) - IFNULL((SELECT IFNULL(SUM(debit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND vendor_id = gld.vendor_id), 0) AS totalAmount, IFNULL(gld.credit, 0) - IFNULL((SELECT IFNULL(SUM(debit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND vendor_id = gld.vendor_id), 0) AS amountDue, IFNULL(gld.credit, 0) - IFNULL((SELECT IFNULL(SUM(debit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND vendor_id = gld.vendor_id), 0) AS balance, '' AS aging, gl.pv_id AS pvId, '' AS pvAppAmt, '' AS pvAmt, '' AS pvRequestId, gl.landed_cost_id AS landedCostId, COALESCE(gl.note, '') AS memo FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id INNER JOIN vendors AS v ON gld.vendor_id = v.id WHERE gl.is_approve = 1 AND gl.is_active = 1
AND gld.company_id = #{filter.companyId}
AND gld.vendor_id = #{filter.vendorId}
AND (SELECT branch_id FROM general_ledger_details WHERE general_ledger_id = gl.id LIMIT 1) = #{filter.branchId}
AND gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE is_active = 1 AND chart_account_type_id IN (SELECT id FROM chart_account_types WHERE name = 'Accounts Payable')) AND gl.sales_order_id IS NULL AND gl.credit_memo_id IS NULL AND gl.purchase_order_id IS NULL AND gl.purchase_return_id IS NULL AND gld.credit > 0 AND (IFNULL(gld.credit, 0) - (IFNULL((SELECT IFNULL(SUM(debit),0) FROM ${tableName} WHERE main_gl_id=gld.main_gl_id AND chart_account_id=gld.chart_account_id AND vendor_id = gld.vendor_id), 0))) > 0 ) ORDER BY `date` ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

